//! 🧪️ Genuine caller grants cover fixed ZIP metadata, stack fragments, CRC inspection, destination copies and output retirement.
use super::*;
use crate::test_oracle::{layout_export_fixture_caller,LAYOUT_EXPORT_FIXTURE_STOCK,LAYOUT_EXPORT_FIXTURE_TURN};
use semio_framework_value::RetainedCloneGrant;
#[derive(Clone,Copy)]enum Action<'a>{Begin(PackageMember),Data(&'a[u8]),Finish,Central(ZipEntry),End(u32)}
impl Action<'_>{fn body(self)->(usize,usize){match self{Self::Begin(m)=>(30+m.name().len(),0),Self::Data(b)=>(b.len(),b.len()),Self::Finish=>(16,0),Self::Central(e)=>(46+e.member.name().len(),0),Self::End(_)=>(22,0)}}fn apply(self,state:&mut ZipState,output:&mut ChunkRope,work:&mut OutputWork)->Result<bool,String>{match self{Self::Begin(m)=>begin(state,output,m,work),Self::Data(b)=>data(state,output,b,work),Self::Finish=>finish(state,output,work),Self::Central(e)=>central(e,output,work),Self::End(offset)=>end(state,output,offset,work)}}}
#[test]fn original_zip_fragments_preserve_all_underfunded_owners_without_temporary_heap_allocations(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){for extent in corpus["chunkExtents"].as_array().unwrap(){let extent=extent.as_u64().unwrap()as usize;let operation=semio_framework_job::Operation::new(semio_framework_job::OperationId(8194),semio_framework_job::RevisionId(1),semio_framework_job::Generation(4),7);let mut caller=layout_export_fixture_caller(operation,operation.generation);let mut output=ChunkRope::new();let mut state=ZipState::default();let sources:Vec<Vec<u8>>=row["members"].as_array().unwrap().iter().map(|member|(0..member["length"].as_u64().unwrap()as usize).map(|i|(i*member["multiplier"].as_u64().unwrap()as usize+member["offset"].as_u64().unwrap()as usize)as u8).collect()).collect();let mut emit=|action:Action<'_>,state:&mut ZipState,output:&mut ChunkRope|{let(length,inspection)=action.body();while !output.has_room(length){caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let step=output.prepare_one(length,cx.retained_grant())?;cx.consume_retained(step.progress())?;Ok(())}).unwrap();}let copy=METADATA+inspection+length+size_of::<usize>()*3;let depth=output.write_depth().unwrap().max(1);let before=state.clone();let bytes_before=(output.len,output.digest,output.allocated_bytes());for denied in[RetainedCloneGrant{maximum_items:1,..LAYOUT_EXPORT_FIXTURE_TURN},RetainedCloneGrant{maximum_copy_bytes:copy-1,..LAYOUT_EXPORT_FIXTURE_TURN},RetainedCloneGrant{maximum_depth:depth-1,..LAYOUT_EXPORT_FIXTURE_TURN}]{caller.turn(denied,|cx|{let mut work=OutputWork::new(cx.retained_grant());let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||action.apply(state,output,&mut work));assert!(!result.unwrap());assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);assert!(!physical.overflowed);assert_eq!(work.receipt(),Default::default());assert_eq!(*state,before);assert_eq!((output.len,output.digest,output.allocated_bytes()),bytes_before);cx.consume_retained(work.receipt())?;Ok(())}).unwrap();}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let mut work=OutputWork::new(cx.retained_grant());let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||action.apply(state,output,&mut work));assert!(result.map_err(crate::Fault::from)?);assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);assert!(!physical.overflowed);assert_eq!(work.receipt().copied_items,2);assert_eq!(work.receipt().copied_bytes,copy);assert_eq!(work.receipt().retained_capacity_bytes,0);cx.consume_retained(work.receipt())?;Ok(())}).unwrap();};for(member,source)in[PackageMember::Document,PackageMember::Preflight,PackageMember::Manifest].into_iter().zip(&sources){emit(Action::Begin(member),&mut state,&mut output);for chunk in source.chunks(extent){emit(Action::Data(chunk),&mut state,&mut output)}emit(Action::Finish,&mut state,&mut output);assert_eq!(state.entry(member.ordinal()).unwrap().crc,row["members"][member.ordinal()]["crc32"].as_u64().unwrap()as u32);}let central_offset=output.len as u32;for i in 0..3{let entry=state.entry(i).unwrap();emit(Action::Central(entry),&mut state,&mut output)}emit(Action::End(central_offset),&mut state,&mut output);drop(emit);let mut wire=Vec::new();for turn in 0..100000{let(chunk,done)=caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let(chunk,done,p)=output.transfer_one(cx.retained_grant())?;cx.consume_retained(p)?;Ok((chunk,done))}).unwrap();if let Some(chunk)=chunk{wire.extend_from_slice(&chunk)}if done{break}assert!(turn<99999);}for i in 0..3{let entry=state.entry(i).unwrap();let at=entry.offset as usize;assert_eq!(&wire[at..at+4],&0x04034b50u32.to_le_bytes());assert_eq!(&wire[at+12..at+14],&33u16.to_le_bytes());let body=at+30+entry.member.name().len();assert_eq!(&wire[body..body+sources[i].len()],sources[i]);let descriptor=body+sources[i].len();assert_eq!(&wire[descriptor..descriptor+4],&0x08074b50u32.to_le_bytes());assert_eq!(&wire[descriptor+4..descriptor+8],&entry.crc.to_le_bytes());}assert_eq!(&wire[wire.len()-22..wire.len()-18],&0x06054b50u32.to_le_bytes());crate::close_output_fixture(&mut output,&mut caller);while state.pop().is_some(){}assert!(state.terminal_is_empty());caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK);}}}
